bool matches(const Cell& cell, const Probe& probe) {
    switch (probe.op) {
        case Op::All:
            return true;
        case Op::Equal:
            return cell.amount == probe.x;
        case Op::Range:
            return cell.amount >= probe.x && cell.amount <= probe.y;
        case Op::IsNull:
            return false;
        case Op::RegionEqual:
            return cell.region == probe.text;
    }
    return false;
}

