Tally walk_row(const Slab& a, const Probe& b, const Gate& c) {
    Tally tally;
    if (!c.read) {
        return tally;
    }
    tally.pages_read = 1;
    for (const auto& cell : a.cells) {
        const bool live = is_live(cell);
        if (b.op == Op::IsNull) {
            if (!live) {
                ++tally.row_count;
            }
            continue;
        }
        if (live && matches(cell, b)) {
            ++tally.row_count;
            tally.sum_amount += cell.amount;
        }
    }
    return tally;
}

